from scipy.stats import spearmanr
import csv

def load_csv(p):
    with open(p) as f: return list(csv.DictReader(f))

cka_rows = load_csv('/root/xling_calib_direction/results_cka_mvp001/cka_matrix_qwen25_7b.csv')
pareto_rows = load_csv('/root/xling_calib_direction/results/pareto/pareto_detail.csv')

cka_map = {}
for r in cka_rows:
    cka_map[(int(r['layer']), r['language'])] = float(r['cka_value'])
auroc_map = {}
for r in pareto_rows:
    auroc_map[(int(r['layer']), r['language'].strip())] = float(r['zs_auroc'])

langs = ['zh','ar','hi','ko','sw']
layers = sorted(set(int(r['layer']) for r in cka_rows))
xs, ys = [], []
for l in layers:
    for lang in langs:
        k = (l, lang)
        if k in cka_map and k in auroc_map:
            xs.append(cka_map[k]); ys.append(auroc_map[k])
rho, p = spearmanr(xs, ys)
print(f'Pooled: rho={rho:.4f}, p={p:.4f}, slope direction={\"negative\" if rho < 0 else \"positive\"}')

for l in [0, 12, 24, 27]:
    lx, ly = [], []
    for lang in langs:
        k = (l, lang)
        if k in cka_map and k in auroc_map:
            lx.append(cka_map[k]); ly.append(auroc_map[k])
    if len(lx) > 1:
        r2, _ = spearmanr(lx, ly)
        print(f'  L{l}: rho={r2:.4f}, slope direction={\"negative\" if r2 < 0 else \"positive\"}')
"
